using System; using System.Configuration; using System.IO; using System.Web; using System.Web.Script.Serialization; using BabcoUnloadCompare.Web.Services;
namespace BabcoUnloadCompare.Web.Handlers { public class DocumentUpload:IHttpHandler,System.Web.SessionState.IRequiresSessionState { public bool IsReusable=>false; public void ProcessRequest(HttpContext c){c.Response.ContentType="application/json";var js=new JavaScriptSerializer();try{int id;if(!int.TryParse(c.Request.Form["receivingId"],out id)||id<=0)throw new InvalidOperationException("Save the receiving draft before uploading a document.");var file=c.Request.Files["file"];UploadSecurity.Validate(file,UploadSecurity.DocumentExt);var safe=UploadSecurity.SafeFileName(file.FileName);var stored=Guid.NewGuid().ToString("N")+Path.GetExtension(safe).ToLowerInvariant();var root=c.Server.MapPath(ConfigurationManager.AppSettings["UnloadCompare.UploadRoot"]);var folder=Path.Combine(root,id.ToString());Directory.CreateDirectory(folder);var full=Path.GetFullPath(Path.Combine(folder,stored));if(!full.StartsWith(Path.GetFullPath(folder),StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Invalid upload path.");file.SaveAs(full);var docId=new DataAccess().SaveDocument(id,safe,stored,file.ContentType,file.ContentLength);c.Response.Write(js.Serialize(new{IsSuccess=true,Message="Receiving sheet uploaded. OCR/AI data remains pending human review.",Data=new{DocumentId=docId,OriginalFileName=safe,ExtractionStatus="Pending Review"}}));}catch(Exception ex){c.Response.StatusCode=400;c.Response.Write(js.Serialize(new{IsSuccess=false,Message=ex.Message}));}} } }
